// Test-only generation of the straight-line Input cases. Render and submit cases are handwritten beside the generated cases.
import fs from 'node:fs';
import {createRequire} from 'node:module';
const require=createRequire(import.meta.url);
const ts=require(require.resolve('typescript',{paths:[process.cwd()+'/extensions/sdk-ts/node_modules']}));
const path='.upstream/current/packages/tui/test/input.test.ts';
const source=ts.createSourceFile(path,fs.readFileSync(path,'utf8'),ts.ScriptTarget.Latest,true);
const cases=[];
function literal(node){if(ts.isStringLiteral(node)||ts.isNoSubstitutionTemplateLiteral(node))return node.text;throw new Error('unsupported literal '+node.getText(source));}
function statements(nodes){
 const out=[];
 for(const node of nodes){
  if(ts.isVariableStatement(node)){
   if(node.declarationList.declarations.length!==1||node.declarationList.declarations[0].name.getText(source)!=='input')throw new Error('unsupported declaration');
   continue;
  }
  if(ts.isForStatement(node)){
   const count=Number(node.condition.right.getText(source));
   if(!Number.isFinite(count))throw new Error('unsupported loop');
   const body=ts.isBlock(node.statement)?node.statement.statements:[node.statement];
   for(let i=0;i<count;i++)out.push(...statements(body));
   continue;
  }
  if(!ts.isExpressionStatement(node)||!ts.isCallExpression(node.expression))throw new Error('unsupported statement '+node.getText(source));
  const call=node.expression;
  const method=call.expression.getText(source);
  if(method==='input.handleInput'||method==='input.setValue')out.push([method==='input.handleInput'?'key':'set',literal(call.arguments[0])]);
  else if(method==='assert.strictEqual'&&call.arguments[0].getText(source)==='input.getValue()')out.push(['want',literal(call.arguments[1])]);
  else throw new Error('unsupported call '+call.getText(source));
 }
 return out;
}
function walk(node,groups=[]){
 if(ts.isCallExpression(node)&&node.expression.getText(source)==='describe'){
  const name=literal(node.arguments[0]);walk(node.arguments[1].body,[...groups,name]);return;
 }
 if(ts.isCallExpression(node)&&node.expression.getText(source)==='it'){
  const name=literal(node.arguments[0]);
  if(groups.includes('render')||name==='submits value including backslash on Enter')return;
  cases.push({name:[...groups.slice(1),name].join('/'),line:source.getLineAndCharacterOfPosition(node.getStart(source)).line+1,steps:statements(node.arguments[1].body.statements)});return;
 }
 ts.forEachChild(node,child=>walk(child,groups));
}
walk(source);
function quote(s){return JSON.stringify(s).replace(/\\u00([0-9a-fA-F]{2})/g,'\\x$1');}
let go=`// Code generated by node test/parity/testdata/pt-tui-input-terminal/port-input-tests.mjs; DO NOT EDIT.\npackage tui\n\nimport "testing"\n\ntype upstreamInputStep struct {kind, value string}\n\nfunc TestUpstreamInputEditing(t *testing.T) {\n for _,tc:=range []struct{name string;steps []upstreamInputStep}{\n`;
for(const row of cases){
 go+=`// ${path}:${row.line}.\n{${quote(row.name)},[]upstreamInputStep{\n`;
 for(const [kind,value] of row.steps)go+=`{${quote(kind)},${quote(value)}},\n`;
 go+='}},\n';
}
go+=`} {t.Run(tc.name,func(t *testing.T){\ninput:=NewInput(InputOptions{})\nfor i,step:=range tc.steps {switch step.kind {case "set":input.SetValue(step.value);case "key":input.HandleInput(step.value);case "want":if got:=input.GetValue();got!=step.value{t.Fatalf("step %d: value=%q, want=%q",i,got,step.value)};default:t.Fatalf("invalid action %q",step.kind)}}\n})}\n}\n`;
fs.writeFileSync('tui/input_editing_upstream_test.go',go);
console.log('Translated',cases.length,'straight-line cases; render/submit remain handwritten.');
